function icon(name, { cls = '', label = '' } = {}) {
  const body = ICONS[name];
  if (!body) return '';
  const a11y = label ? `role="img" aria-label="${label}"` : 'aria-hidden="true"';
  return `<svg class="i i-${name}${cls ? ' ' + cls : ''}" viewBox="0 0 256 256" fill="currentColor" ${a11y}>${body}</svg>`;
}
/** Vidas: n corações preenchidos. */
const hearts = n => (n > 0 ? Array.from({ length: n }, () => icon('heart', { cls: 'heart' })).join('') : '—');
/** Selo de posição: 1º/2º/3º em ouro, prata e bronze; o resto só o número. */
const rankBadge = pos => `<span class="rank${pos <= 3 ? ' r' + pos : ''}" aria-label="${pos}º lugar">${pos}</span>`;
// <span data-ic="nome"> no HTML vira o ícone (header e menu da conta)
document.querySelectorAll('[data-ic]').forEach(el => { el.outerHTML = icon(el.dataset.ic); });
document.querySelector('#acctBtn .chev')?.insertAdjacentHTML('afterbegin', icon('chevron-down'));
document.querySelector('#pav')?.insertAdjacentHTML('afterbegin', icon('user'));
